<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';$user=require_role('donor');$pdo=db();$stmt=$pdo->prepare("SELECT a.*,dp.status pledge_status,cr.title,cr.collection_location,c.organization_name,qt.token FROM appointments a JOIN donation_pledges dp ON dp.id=a.pledge_id JOIN clothing_requests cr ON cr.id=dp.request_id JOIN charities c ON c.id=cr.charity_id LEFT JOIN donation_qr_tokens qt ON qt.appointment_id=a.id WHERE dp.donor_id=? ORDER BY a.appointment_date DESC,a.time_slot DESC");$stmt->execute([$user['id']]);$appointments=$stmt->fetchAll();$pageTitle='Your appointments';require __DIR__ . '/../includes/header.php'; ?>
<script src="https://cdn.jsdelivr.net/npm/qrcodejs@1.0.0/qrcode.min.js"></script>
<section class="dashboard"><div class="shell"><div class="subnav"><a href="<?=e(url('donor/dashboard.php'))?>">Dashboard</a><a href="<?=e(url('donor/pledges.php'))?>">My donations</a><a class="is-active" href="<?=e(url('donor/appointments.php'))?>">Appointments</a><a href="<?=e(url('donor/passport.php'))?>">Passport</a></div><div class="welcome-row"><div><span class="eyebrow">Bring your QR pass</span><h1>Your drop-off appointments</h1><p>A charity can scan or manually enter the one-time code to check you in.</p></div></div><?php if(!$appointments):?><div class="empty"><span class="empty-icon">◷</span>No appointment booked yet. Approved pledges can be scheduled from My Donations.</div><?php else:?><div class="request-grid"><?php foreach($appointments as $a):?><article class="panel"><span class="status <?=e(status_class($a['status']))?>"><?=e(str_replace('_',' ',$a['status']))?></span><h2 style="margin:13px 0 7px"><?=e($a['title'])?></h2><p class="section-description"><?=e($a['organization_name'])?><br>📅 <?=format_date($a['appointment_date'],'D, d M Y')?> · <?=e(substr($a['time_slot'],0,5))?><br>📍 <?=e($a['collection_location'])?></p><?php if($a['status']==='booked'&&$a['token']):?><div class="qr-box" id="qr-<?=$a['id']?>"></div><p class="help">Check-in code: <strong><?=e(substr($a['token'],0,12))?>…</strong></p><script>document.addEventListener('DOMContentLoaded',()=>new QRCode(document.getElementById('qr-<?=$a['id']?>'),{text:'GIFTLY:<?=e($a['token'])?>',width:190,height:190,colorDark:'#20201E',colorLight:'#FFFFFF'}));</script><?php elseif($a['status']==='checked_in'):?><p class="flash flash-success">Checked in—thank you for arriving.</p><?php endif;?></article><?php endforeach;?></div><?php endif;?></div></section>
<?php require __DIR__ . '/../includes/footer.php'; ?>
